ARO DE PAZ','5','2005-06-07','(16) 3475-9140',NULL,'CLAUDIACRISTINAPAROPAZ@GMAIL.COM',NULL,'Área de zootecnia, com ênfase em genética e melhoramento dos animais domésticos e estatística aplicada',NULL,NULL,'http://lattes.cnpq.br/1007816901824719','S','S','S','E','A',NULL,1,1,NULL),(855,'HENRIQUE NUNES DE OLIVEIRA','5','2006-04-12','(14) 3811-7187','(14) 3811-7197','HNUNES@FCA.UNESP.BR',NULL,'Atua na área de zootecnia, com ênfase em genética e melhoramento dos animais domésticos',NULL,NULL,'http://lattes.cnpq.br/5593441035110683','N','S','S','E','I',NULL,7,1,NULL),(856,'VERA LUCIA CARDOSO','5','2006-02-06','(16) 3637-1849','(16) 3637-1849','VLCARDOSO@NETSITE.COM.BR',NULL,'Área de zootecnia, com ênfase em genética e melhoramento dos animais domésticos',NULL,NULL,NULL,'S','S','S','E','I',NULL,7,1,NULL),(859,'JULIANA RAMOS MARTINS','2','2008-09-22','(16) 3315-3153',NULL,'JULIANARMARTINS@USP.BR',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'I',NULL,NULL,26,'2012-11-14'),(860,'PAULO ROBERTO D\'AURIA VIEIRA DE GODOY','2','2008-10-10','(16) 3315-3082',NULL,'PAULODAURIA@YAHOO.COM',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'I',NULL,NULL,8,'2013-04-13'),(861,'RICARDO ZORZETTO NICOLIELLO VÊNCIO','5','2008-01-01','(16) 3315-0526','(16) 3633-0069','RVENCIO@USP.BR',NULL,'BSc. in Physics, MSc. in Statistics and PhD. in Bioinformatics by the University of São Paulo (USP), I have been working on the creation of mathematical methods for the solution of problems in Biology and Medicine. More specifically, I have been working on transcript enumeration and microarray data, using Bayesian ideas. In 2008 I joined the University of São Paulo\'s Medical School at Ribeirão Preto (FMRP-USP) as Assistant Professor to conduct research and teaching activities on Bioinformatics at the Genetics Department. Questions and comments regarding my work are always welcome.<br>\r\nBacharel em Física, Mestre em Estatística e Doutor em Bioinformática pela Universidade de São Paulo (USP), venho trabalhando na criação de método matemáticos para a solução de problemas em Biologia e Medicina. Mais especificamente, venho trabalhando sobre dados de enumeração de transcritos e microarranjos, usando idéias Bayesianas. Em 2008 integrei-me ao corpo docente da Faculdade de Medicina de Ribeirão Preto, na Universidade de São Paulo (FMRP-USP), como Professor Doutor (MS-3) para desenvolver atividades de pesquisa e ensino em Bioinformática no Departamento de Genética. Perguntas e comentários sobre o meu trabalho são sempre bem-vindas.',NULL,'imagens/fotos/ricardovencio.jpg','http://buscatextual.cnpq.br/buscatextual/visualizacv.jsp?id=K4766457E0','S','S','S','E','I',NULL,1,28,NULL),(862,'ANGEL MAURICIO CASTRO GAMERO','2','2008-11-17','(16) 3315-2671',NULL,'AMCGEN@USP.BR',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'I',NULL,NULL,15,'2012-12-15'),(863,'DANIEL ANTUNES MORENO','2','2008-07-07','(16) 3315-2651',NULL,'DANIELMORENO@USP.BR',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'I',NULL,NULL,15,'2012-08-25'),(864,'DANIEL MACEDO DE MELO JORGE','2','2008-11-13','(16) 3315-4588',NULL,'DANIELMACEDO.JORGE@GMAIL.COM',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'I',NULL,NULL,9,'2013-05-10'),(865,'DANILO JORDÃO XAVIER','2','2008-12-15','(16) 3315-3082',NULL,'DANJORDAN55@YAHOO.COM.BR',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'I',NULL,NULL,8,'2013-06-15'),(866,'DAVID SANTOS MARCO ANTONIO','2','2008-07-07','(16) 3315-3153',NULL,'DSMARCOANTONIO@YAHOO.COM.BR',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'I',NULL,NULL,26,'2012-08-11'),(867,'LISANDRA MESQUITA BATISTA','2','2008-11-13','(16) 3315-3256',NULL,'LIMESQ@GMAIL.COM',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'I',NULL,NULL,7,'2012-07-16'),(868,'TATHYANA RACHEL PALO MELLO','2','2008-11-13','(16) 3315-3153',NULL,'TMELLO@USP.BR',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'I',NULL,NULL,26,'2013-01-26'),(869,'OMAR ARVEY MARTINEZ CARANTÓN','2','2008-07-07','(16) 3315-3077',NULL,'OMARAPIS@YAHOO.COM.BR',NULL,NULL,NULL,NULL,NULL,NULL,NULL,