 SOUZA RODRIGUES','1','2011-02-04','(16) 3315-4503',NULL,'IULIANAS@GMAIL.COM',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'I',NULL,NULL,9,'2015-02-23'),(1046,'DORA YOVANA BARRIOS LEAL','2','2013-03-11','(16) 3315-3103',NULL,'DORABARRIOSLEAL@USP.BR',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'I',NULL,NULL,3,'2017-04-08'),(967,'APARECIDA MARIA FONTES','5','2009-02-01','(16) 3315-3151','(16) 3623-7215','APARECIDAMFONTES@USP.BR',NULL,'Tem experiência nas áreas de Biologia do Desenvolvimento, Genética Molecular e Biologia Tumoral, Hemofilia, Terapia Celular e Células-Tronco, atuando nos seguintes temas:\r\n\r\n(1) Câncer: sendo o interesse principal tumores pediátricos meduloblastoma e leucemia mieloide aguda visando compreender mecanismos reguladores pós-transcricionais dos genes HOX com o objetivo de identificar novos alvos terapêuticos anti-tumorais;\r\n\r\n(2) Doenças do erro inato do metabolismo de disfunção lisossomal, como doença de Gaucher, Pompe, Fabry sendo o interesse principal as análises genotípica e fenotípica para compreender a associação entre gene modificadores e características clínicas, bem como, as alterações herdadas que sirvam como prognóstico e alvos terapêuticos;\r\n\r\n(3) Biotecnologia: sendo o interesse principal utilizar a engenharia genética e a biologia sintética para o desenvolvimento de biofármacos para Terapia de Reposição em Hemofilia A, Hemofilia B e Doença de Gaucher utilizando linhagens celulares humanas e modelos murinos para investigar a funcionalidade in vitro e in vivo desses biofármacos.',NULL,NULL,'http://lattes.cnpq.br/2104806254317258','S','S','S','D','A',NULL,3,31,NULL),(968,'RODRIGO ALEXANDRE PANEPUCCI','5','2009-02-01','(16) 3315-2223',NULL,'RAPANE@LGMB.FMRP.USP.BR',NULL,'Possui Bacharelado em Ciências Biológicas (1998) e Mestrado em Genética e Evolução (2001), ambos pela Universidade Federal de São Carlos (UFSCar), Doutorado em Ciências Médicas (2006) pelo Departamento de Clínica Médica da Faculdade de Medicina da Universidade de São Paulo de Ribeirão Preto (FMRP-USP). Tem experiência na área de Bioquímica, com ênfase em Biologia Molecular, atuando principalmente com estudos de expressão gênica (SAGE, Microarray, Real Time PCR) de células tronco adultas (Hematopoéticas e Mesenquimais) e de neoplasias do sangue (Leucemias e Linfomas). Atualmente, é pesquisador científico e tecnológico, contratado pela Fundação Hemocentro de Ribeirão Preto (FUNDHERP).',NULL,NULL,'http://lattes.cnpq.br/2726230162746149','S','S','N','E','A',NULL,9,10,NULL),(1048,'NATHÁLIA JOANNE BISPO CEZAR','2','2013-03-11','(16) 3315-3246',NULL,'NATHINHACNC@HOTMAIL.COM',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'I',NULL,NULL,17,'2017-06-28'),(970,'JOSIANE LÍLIAN DOS SANTOS SCHIAVINATO','2','2011-04-08','(16) 2101-9365',NULL,'JOSILILIAN@GMAIL.COM',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'I',NULL,NULL,17,'2014-10-09'),(971,'NATALIA FAGUNDES CAGNIN','2','2011-04-08','(16) 3315-3050',NULL,'NACAGNIN@YAHOO.COM.BR',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'I',NULL,NULL,4,'2015-06-30'),(972,'FLÁVIA GAONA DE OLIVEIRA GENNARO','2','2011-04-18','(16) 3315-3076',NULL,'FLAVIAGAONA@GMAIL.COM',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'I',NULL,NULL,25,NULL),(973,'LARISSA OLIVEIRA GUIMARÃES','2','2011-04-14','(16) 3315-3076',NULL,'LARAGENETICA@YAHOO.COM.BR',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'I',NULL,NULL,31,'2015-10-24'),(974,'RAFAEL SALES DE ALBUQUERQUE','2','2011-05-04','(16) 3315-2622',NULL,'RAFAEL-RSA@USP.BR',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'I',NULL,NULL,17,'2015-05-30'),(975,'RICARDO BONFIM SILVA','2','2011-05-09','(16) 2101-9371',NULL,'BONFIM.RICARDO@USP.BR',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'I',NULL,NULL,31,'2015-11-19'),(976,'FLÁVIA ANAN SAIKI','4','2010-01-01','(16) 3315-3050',NULL,'FLAVIASAIKI@YAHOO.COM.BR',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'I',8,NULL,4,NULL),(977,'CELSO TEIXEIRA MENDES JUNIOR','5','2009-02-01','(16) 3315-0417','(16) 3315-4838','CTMENDES@FFCLRP.