br/4911087156577247','N','S','N','E','A',NULL,4,17,NULL),(1122,'FRANCIS DE MORAIS FRANCO NUNES','5','2015-02-10','(16) 3306-6753',NULL,'FRANCIS.NUNES@UFSCAR.BR',NULL,'Atualmente é Professor Adjunto II do Departamento de Genética e Evolução da Universidade Federal de São Carlos e Vice-Coordenador do Curso de Bacharelado em Biotecnologia. Foi Coordenador (Instructor - Primary Contact (PI)) do Time Paulista \"Brasil-SP\" (UFSCar-USP-UNESP) na Competição Internacional de Biologia Sintética \"iGEM 2014\" (http://igem.org/Main_Page , http://2014.igem.org/Team:Brasil-SP), que foi premiada com Medalha de Bronze. É Secretário Regional da SBPC-SP (subárea III) e Membro da Diretoria da IUSSI-Seção Brasileira (Tesoureiro). Tem experiência na área de Genética do Desenvolvimento e Expressão Gênica, com ênfase em insetos, envolvendo as linhas de pesquisa: determinação de castas e sexo, regulação hormonal, metamorfose, comportamento social, efeitos de dietas sobre o envelhecimento, estudos de genoma e transcriptoma, análise de regiões reguladoras da expressão gênica, promotores, RNAs não-codificadores (principalmente microRNAs), microarrays, silenciamento gênico (RNAi), next-generation sequencing e bioinformática.',NULL,NULL,'http://lattes.cnpq.br/1974857490729279','S','S','S','E','A',NULL,8,26,NULL),(1123,'SIMONE DA COSTA E SILVA CARVALHO','2','2015-05-13','(16) 2101-9368',NULL,'SIMONEDACOSTAESILVA@GMAIL.COM',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'I',NULL,NULL,14,'2019-08-17'),(1124,'ÉRICO TORRIERI','2','2015-06-12','(16) 3315-4588',NULL,'ERICOTORRIERI@GMAIL.COM',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'I',NULL,NULL,14,'2021-03-13'),(1125,'PAMELA VIANI DE ANDRADE','2','2015-06-26','(16) 99112-2494',NULL,'PAMELAVIANI@GMAIL.COM',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'I',NULL,NULL,36,'2019-10-17'),(1126,'JOÃO PAULO LOPES DA SILVA','2','2015-07-01','(16) 98176-1460',NULL,'JOAOPAULO_LS@YAHOO.COM.BR',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'I',NULL,NULL,17,'2019-